<?php
declare(strict_types=1);
$sql=[
"CREATE TABLE svc_resources (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,service_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,server_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,external_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,resource_role VARCHAR(24) CHARACTER SET ascii NOT NULL DEFAULT 'PRIMARY',operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,imported BOOLEAN NOT NULL DEFAULT FALSE,evidence_hash CHAR(64) CHARACTER SET ascii NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_svc_resource(service_id,resource_role),UNIQUE KEY uq_svc_external(server_id,external_id),UNIQUE KEY uq_svc_resource_operation(operation_id),FOREIGN KEY(service_id) REFERENCES svc_services(id)) ENGINE=InnoDB",
"CREATE TABLE svc_period_evidence (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,period_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,evidence_encrypted LONGTEXT NOT NULL,fingerprint CHAR(64) CHARACTER SET ascii NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(period_id) REFERENCES svc_periods(id)) ENGINE=InnoDB",
"CREATE TRIGGER svc_period_binding BEFORE UPDATE ON svc_periods FOR EACH ROW BEGIN IF OLD.service_id<>NEW.service_id OR OLD.customer_id<>NEW.customer_id OR OLD.generation<>NEW.generation OR OLD.billing_request_id<>NEW.billing_request_id OR OLD.price_id<>NEW.price_id OR OLD.cycle_snapshot<>NEW.cycle_snapshot OR (OLD.status='VERIFIED' AND (NOT(OLD.starts_at <=> NEW.starts_at) OR NOT(OLD.ends_at <=> NEW.ends_at) OR NEW.status<>'VERIFIED')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable verified period'; END IF; END",
];foreach(['svc_resources','svc_period_evidence'] as $table){foreach(['UPDATE','DELETE'] as $verb){$sql[]="CREATE TRIGGER {$table}_".strtolower($verb)." BEFORE $verb ON $table FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable service resource evidence'";}}return $sql;
